--
-- Table structure for table `fact_applications`
--

DROP TABLE IF EXISTS `fact_applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_applications` (
  `application_id` int NOT NULL,
  `date_key` int NOT NULL,
  `technology_key` int NOT NULL,
  `profile_key` int NOT NULL,
  `country_key` int NOT NULL,
  `code_challenge_score` tinyint NOT NULL,
  `technical_interview_score` tinyint NOT NULL,
  `score_gap` smallint NOT NULL,
  `is_hired` tinyint NOT NULL,
  PRIMARY KEY (`application_id`),
  KEY `idx_fact_date` (`date_key`),
  KEY `idx_fact_technology` (`technology_key`),
  KEY `idx_fact_profile` (`profile_key`),
  KEY `idx_fact_country` (`country_key`),
  CONSTRAINT `fk_fact_country` FOREIGN KEY (`country_key`) REFERENCES `dim_country` (`country_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_fact_date` FOREIGN KEY (`date_key`) REFERENCES `dim_date` (`date_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_fact_profile` FOREIGN KEY (`profile_key`) REFERENCES `dim_candidate_profile` (`profile_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_fact_technology` FOREIGN KEY (`technology_key`) REFERENCES `dim_technology` (`technology_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_code_challenge_score` CHECK ((`code_challenge_score` between 0 and 10)),
  CONSTRAINT `chk_is_hired` CHECK ((`is_hired` in (0,1))),
  CONSTRAINT `chk_technical_interview_score` CHECK ((`technical_interview_score` between 0 and 10))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

